PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_batches(id TEXT PRIMARY KEY, name TEXT NOT NULL, sha256 TEXT NOT NULL UNIQUE, state TEXT NOT NULL DEFAULT 'staged', recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, batch_id TEXT REFERENCES import_batches(id), path TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, sha256 TEXT NOT NULL, bytes INTEGER NOT NULL, content TEXT NOT NULL, tier INTEGER NOT NULL CHECK(tier BETWEEN 1 AND 6), kind TEXT NOT NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS immutable_sources_update BEFORE UPDATE ON sources BEGIN SELECT RAISE(ABORT,'Original sources are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_sources_delete BEFORE DELETE ON sources BEGIN SELECT RAISE(ABORT,'Original sources are immutable'); END;
CREATE TABLE IF NOT EXISTS chunks(id INTEGER PRIMARY KEY, source_id TEXT NOT NULL REFERENCES sources(id), line_start INTEGER NOT NULL, line_end INTEGER NOT NULL, text TEXT NOT NULL, UNIQUE(source_id,line_start));
CREATE VIRTUAL TABLE IF NOT EXISTS source_fts USING fts5(text, source_id UNINDEXED, line_start UNINDEXED, line_end UNINDEXED);
CREATE TABLE IF NOT EXISTS entities(id TEXT PRIMARY KEY, name TEXT NOT NULL, kind TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS assertions(id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), predicate TEXT NOT NULL, value TEXT NOT NULL, category TEXT NOT NULL, canon TEXT NOT NULL CHECK(canon IN ('confirmed','provisional','disputed','superseded','rejected','unknown')), operation TEXT NOT NULL DEFAULT 'unknown', confidence TEXT NOT NULL DEFAULT 'unspecified', date_json TEXT NOT NULL, valid_from TEXT, valid_to TEXT, scope TEXT NOT NULL DEFAULT 'interval' CHECK(scope IN ('point','interval','undated')), recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, superseded_by TEXT REFERENCES assertions(id), notes TEXT NOT NULL DEFAULT '', batch_id TEXT REFERENCES import_batches(id));
CREATE INDEX IF NOT EXISTS assertion_lookup ON assertions(entity_id,predicate,valid_from,valid_to);
CREATE TABLE IF NOT EXISTS evidence(id INTEGER PRIMARY KEY, assertion_id TEXT NOT NULL REFERENCES assertions(id), source_id TEXT NOT NULL REFERENCES sources(id), line_start INTEGER NOT NULL, line_end INTEGER NOT NULL, excerpt TEXT NOT NULL, UNIQUE(assertion_id,source_id,line_start));
CREATE TABLE IF NOT EXISTS timeline(id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, date_json TEXT NOT NULL, canon TEXT NOT NULL, operation TEXT NOT NULL DEFAULT 'unknown', source_id TEXT REFERENCES sources(id), line_start INTEGER, line_end INTEGER, note TEXT NOT NULL DEFAULT '', batch_id TEXT REFERENCES import_batches(id));
CREATE TABLE IF NOT EXISTS issues(id TEXT PRIMARY KEY, fingerprint TEXT UNIQUE, kind TEXT NOT NULL CHECK(kind IN ('conflict','missing')), priority TEXT NOT NULL, category TEXT NOT NULL, title TEXT NOT NULL, known_state TEXT NOT NULL DEFAULT '', question TEXT NOT NULL DEFAULT '', state TEXT NOT NULL DEFAULT 'open', a_id TEXT REFERENCES assertions(id), b_id TEXT REFERENCES assertions(id), answer TEXT, postponed_until TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS decisions(id TEXT PRIMARY KEY, issue_id TEXT NOT NULL REFERENCES issues(id), action TEXT NOT NULL, explanation TEXT NOT NULL, before_json TEXT NOT NULL, after_json TEXT NOT NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, action TEXT NOT NULL, target TEXT NOT NULL, before_json TEXT, after_json TEXT, explanation TEXT NOT NULL, recorded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS immutable_audit_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'Audit is append only'); END;
CREATE TRIGGER IF NOT EXISTS immutable_audit_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'Audit is append only'); END;
CREATE TRIGGER IF NOT EXISTS immutable_decisions_update BEFORE UPDATE ON decisions BEGIN SELECT RAISE(ABORT,'Decisions are append only'); END;
CREATE TRIGGER IF NOT EXISTS immutable_decisions_delete BEFORE DELETE ON decisions BEGIN SELECT RAISE(ABORT,'Decisions are append only'); END;
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
